$success='';$error='';$inviteUrl='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{
    $action=(string)($_POST['action']??'');$reason=(string)($_POST['reason']??'');
    if($action==='lifecycle'){$account=account_admin_update_lifecycle($pdo,$admin,(string)$account['public_id'],$_POST);$success='Account lifecycle updated.';}
    elseif($action==='package'){$account=account_admin_change_package($pdo,$admin,(string)$account['public_id'],(string)($_POST['package_id']??''),$reason);$success='Account package updated.';}
    elseif($action==='add_member'){account_admin_add_member($pdo,$admin,(string)$account['public_id'],(string)($_POST['user_identifier']??''),(string)($_POST['account_role']??'member'),$reason);$success='Account member added.';}
