    elseif($action==='remove_member'){account_admin_remove_member($pdo,$admin,(string)$account['public_id'],(int)($_POST['user_id']??0),$reason);$success='Member removed.';}
    elseif($action==='transfer_owner'){$account=account_admin_transfer_owner($pdo,$admin,(string)$account['public_id'],(int)($_POST['user_id']??0),$reason);$success='Account ownership transferred.';}
    elseif($action==='invite_member'){$invite=account_membership_create_invitation($pdo,$config,$admin,(string)$account['public_id'],(string)($_POST['email']??''),(string)($_POST['account_role']??'member'),!empty($_POST['reserve_seat']),(int)($_POST['expires_days']??7),$reason);$inviteUrl=(string)($invite['invite_url']??'');$success=$invite['delivery_status']==='sent'?'Invitation created and sent.':'Invitation created. Copy the secure link below.';}
    elseif($action==='resend_invite'){$invite=account_membership_resend_invitation($pdo,$config,$admin,(string)($_POST['invitation_id']??''),(int)($_POST['expires_days']??7),$reason);$inviteUrl=(string)($invite['invite_url']??'');$success=$invite['delivery_status']==='sent'?'Invitation token rotated and resent.':'Invitation token rotated. Copy the new secure link below.';}
    elseif($action==='revoke_invite'){account_membership_revoke_invitation($pdo,$admin,(string)($_POST['invitation_id']??''),$reason);$success='Invitation revoked.';}
    elseif($action==='set_token_override'){$mode=(string)($_POST['token_mode']??'set');$value=$mode==='unlimited'?null:max(0,(int)($_POST['token_value']??0));account_admin_set_override($pdo,$admin,(string)$account['public_id'],'monthly_ai_token_allowance',$value,trim((string)($_POST['expires_at']??''))?:null,$reason);$success='AI token entitlement override saved.';}
    elseif($action==='set_member_override'){account_admin_set_override($pdo,$admin,(string)$account['public_id'],'member_limit',max(1,(int)($_POST['member_limit']??1)),trim((string)($_POST['expires_at']??''))?:null,$reason);$success='Member-limit entitlement override saved.';}
    elseif($action==='set_feature_override'){
        $feature=preg_replace('/[^a-z0-9_.-]+/','',strtolower(trim((string)($_POST['feature_key']??''))))?:'';if($feature==='')throw new InvalidArgumentException('Feature key is required.');
        $type=(string)($_POST['value_type']??'boolean');$raw=trim((string)($_POST['feature_value']??''));if($type==='boolean')$value=in_array(strtolower($raw),['1','true','yes','on'],true);elseif($type==='integer')$value=(int)$raw;elseif($type==='json'){$value=json_decode($raw,true,512,JSON_THROW_ON_ERROR);}else $value=$raw;
        account_admin_set_override($pdo,$admin,(string)$account['public_id'],'feature.'.$feature,$value,trim((string)($_POST['expires_at']??''))?:null,$reason);$success='Feature entitlement override saved.';
    }elseif($action==='revoke_override'){account_admin_revoke_override($pdo,$admin,(string)$account['public_id'],(string)($_POST['entitlement_key']??''),$reason);$success='Entitlement override revoked.';}
    else throw new RuntimeException('Unknown account action.');
}catch(Throwable $e){$error=$e->getMessage();}$account=account_admin_get($pdo,(int)$account['id'])??$account;}
