<form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="set_member_override"><h3>Member-limit override</h3><label>Member limit<input type="number" min="<?=h((string)count($members))?>" name="member_limit" value="<?=h((string)$ent['values']['member_limit'])?>" required></label><label>Expires at<input type="datetime-local" name="expires_at"></label><label>Reason<textarea name="reason" rows="2" required></textarea></label><button>Save member override</button></form></div>
<details><summary>+ Feature entitlement override</summary><form method="post" class="adminFeatureOverrideForm"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="set_feature_override"><label>Feature key<input name="feature_key" required placeholder="advanced_exports"></label><label>Type<select name="value_type"><option value="boolean">Boolean</option><option value="integer">Integer</option><option value="string">String</option><option value="json">JSON</option></select></label><label>Value<input name="feature_value" required placeholder="true"></label><label>Expires at<input type="datetime-local" name="expires_at"></label><label>Reason<input name="reason" required maxlength="500"></label><button>Save feature override</button></form></details>
<h3>Override registry</h3><div class="tableWrap"><table><thead><tr><th>Key</th><th>Status</th><th>Value</th><th>Expiry</th><th>Reason</th><th></th></tr></thead><tbody><?php foreach($overrides as $o):?><tr><td><code><?=h((string)$o['entitlement_key'])?></code></td><td><?=h((string)$o['status'])?></td><td><code><?=h((string)($o['value_json']??'null'))?></code></td><td><?=h((string)($o['expires_at']?:'—'))?></td><td><?=h((string)$o['reason'])?></td><td><?php if($o['status']==='active'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$account['public_id'])?>"><input type="hidden" name="action" value="revoke_override"><input type="hidden" name="entitlement_key" value="<?=h((string)$o['entitlement_key'])?>"><input name="reason" required placeholder="Revocation reason"><button class="button secondary">Revoke</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$overrides):?><tr><td colspan="6" class="empty">No account-level overrides. Package entitlements are authoritative.</td></tr><?php endif?></tbody></table></div></section>
<section class="card"><span class="eyebrow">AUDIT</span><h2>Account administration history</h2><?php foreach($events as $e):?><div class="historyItem"><strong><?=h(ucwords(str_replace('_',' ',(string)$e['event_type'])))?></strong><div class="meta"><?=h((string)$e['created_at'])?> · <?=h((string)($e['actor_username']?:'System'))?><?php if($e['subject_username']):?> · @<?=h((string)$e['subject_username'])?><?php endif?></div><p><?=h((string)$e['reason'])?></p></div><?php endforeach?><?php if(!$events):?><p class="empty">No V1.30 account administration events yet.</p><?php endif?></section>
</main></body></html>
